package app.gtdial.lab;

import org.json.JSONObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Windowed working-set aggregation; mode, reps and equipment identity define comparability. */
final class AnalysisStrengthSummary {
    static String key(JSONObject entry){String mode=entry.optString("loadMode"),equipment=entry.optString("equipmentProfileId");return entry.optString("variantId")+"|"+mode+"|"+entry.optString("repConvention","REPS_AS_ENTERED")+"|"+(("MACHINE".equals(mode)||"ASSISTANCE".equals(mode))&&equipment.isEmpty()?"missing:"+entry.optString("id"):equipment);}
    static List<JSONObject> choices(AnalysisSnapshot.Source source){Map<String,JSONObject> result=new java.util.TreeMap<>();for(List<JSONObject> entries:source.entries.values())for(JSONObject entry:entries)if(!entry.optBoolean("removed"))result.putIfAbsent(key(entry),NutritionModels.object("key",key(entry),"label",entry.optString("nameSnapshot")+" · "+entry.optString("loadMode")+(entry.optString("equipmentProfileId").isEmpty()?"":" · "+entry.optString("equipmentProfileId"))));return new ArrayList<>(result.values());}
    private static final class Aggregate {int sessions,sets,reps,gaps,excluded,unknownActive;long active;final Set<Integer> days=new HashSet<>();final Map<String,Integer> groups=new java.util.TreeMap<>();final Map<String,Exercise> exercises=new LinkedHashMap<>();}
    private static final class Exercise {String mode,variant,group;boolean comparable;int sets,reps,maxReps;final Set<String> sessions=new HashSet<>();final Map<Integer,Long> best=new java.util.TreeMap<>();final Map<Integer,Map<Integer,Long>> daily=new HashMap<>();}
    private static String group(String original){switch(original){case "Грудь":return "chest";case "Спина":return "back";case "Ноги":return "legs";case "Плечи":return "shoulders";case "Руки":return "arms";case "Корпус":return "core";default:return "other";}}
    static void build(AnalysisSnapshot.Builder b){AnalysisSnapshot.Selection selection=b.selection;Aggregate current=new Aggregate(),previous=new Aggregate();for(JSONObject workout:b.source.workouts){if(!"SAVED".equals(workout.optString("status"))||!"strength".equals(workout.optString("typeId"))||!ExpansionModels.PHONE.equals(workout.optString("source")))continue;int index=selection.index(AnalysisSnapshot.workoutDate(workout,selection.zone));Aggregate a=selection.current(index)?current:previous;a.sessions++;a.days.add(index);Double active=AnalysisSnapshot.validNumber(workout,"elapsedActiveMillis",0,Long.MAX_VALUE);if(active!=null)a.active+=active.longValue();else {a.excluded++;a.unknownActive++;}boolean gap=workout.optBoolean("recoveryGapUnknown");if(gap)a.gaps++;for(JSONObject entry:b.source.entries.getOrDefault(workout.optString("id"),Collections.emptyList())){if(entry.optBoolean("removed"))continue;String mode=entry.optString("loadMode"),convention=entry.optString("repConvention","REPS_AS_ENTERED");if(!StrengthCatalog.loadMode(mode)||!"REPS_AS_ENTERED".equals(convention)){a.excluded++;continue;}String key=key(entry),equipment=entry.optString("equipmentProfileId");boolean comparable=!("MACHINE".equals(mode)||"ASSISTANCE".equals(mode))||!equipment.isEmpty();Exercise e=a.exercises.computeIfAbsent(key,k->new Exercise());e.mode=mode;e.variant=StrengthCatalog.find(entry.optString("variantId"))==null?null:entry.optString("variantId");e.group=group(entry.optString("group"));e.comparable=comparable;
            for(JSONObject set:b.source.sets.getOrDefault(entry.optString("id"),Collections.emptyList())){if(!"DONE".equals(set.optString("state"))||!"WORK".equals(set.optString("setKind")))continue;Object repsValue=set.opt("reps");if(!(repsValue instanceof Integer)&&!(repsValue instanceof Long)){a.excluded++;continue;}long reps=((Number)repsValue).longValue();if(reps<1||reps>1000){a.excluded++;continue;}Double grams=AnalysisSnapshot.validNumber(set,"loadGrams",0,2000000);if(!"BODYWEIGHT".equals(mode)&&(grams==null||Math.rint(grams)!=grams)){a.excluded++;continue;}a.sets++;a.reps+=(int)reps;a.groups.merge(e.group,1,Integer::sum);e.sets++;e.reps+=(int)reps;e.sessions.add(workout.optString("id"));if("BODYWEIGHT".equals(mode))e.maxReps=Math.max(e.maxReps,(int)reps);else{best(e.best,(int)reps,grams.longValue(),mode);if(!gap&&comparable)best(e.daily.computeIfAbsent(index,k->new java.util.TreeMap<>()),(int)reps,grams.longValue(),mode);}}}}
        JSONObject domain=b.domain("strength",current.days.size(),current.sessions>=2&&current.excluded==0?"SUFFICIENT":"LIMITED",current.gaps>0?new String[]{"RECOVERY_GAP"}:new String[]{});b.common(domain,current.days.size(),current.days.size(),current.excluded,current.sets);b.metric(domain,"period.savedSessionCount",current.sessions,"count","saved_phone_strength_sessions",current.sessions);b.metric(domain,"period.doneWorkSetCount",current.sets,"count","done_work_sets_excluding_warmup",current.sets);b.metric(domain,"period.totalReps",current.reps,"reps","registered_reps_as_entered",current.sets);b.metric(domain,"period.registeredActiveMillis",current.unknownActive>0?null:current.active,"ms","saved_session_active_time_unknown_gaps_separate",current.sessions);b.metric(domain,"period.recoveryGapSessionCount",current.gaps,"count","sessions_with_unknown_recovery_gaps",current.sessions);for(String group:current.groups.keySet())b.metric(domain,"period.groupWorkSetCounts."+group,current.groups.get(group),"count","done_work_sets_not_physiological_load",current.sets);
        int ref=0,missingEquipment=0;for(String key:selection.exercises){Exercise now=current.exercises.get(key),before=previous.exercises.get(key);if(now==null&&before==null)continue;Exercise description=now==null?before:now;String path="exercise[e"+(++ref)+"].";b.metric(domain,path+"loadMode",description.mode,"mode","entry_load_convention",now==null?0:now.sets);b.metric(domain,path+"group",description.group,"group","normalized_movement_group",now==null?0:now.sets);if(description.variant!=null)b.metric(domain,path+"variantId",description.variant,"variantId","builtin_catalog_variant",now==null?0:now.sets);b.metric(domain,path+"comparable",description.comparable,"boolean","same_variant_mode_rep_convention_equipment",now==null?0:now.sets);if(!description.comparable)missingEquipment++;b.metric(domain,path+"doneWorkSetCount",now==null?0:now.sets,"count","registered_work_sets",now==null?0:now.sets);if("BODYWEIGHT".equals(description.mode)){b.metric(domain,path+"maxRepsInWorkSet",now==null?null:now.maxReps,"reps","bodyweight_repetitions_without_invented_mass",now==null?0:now.sets);continue;}
            for(int reps:selection.repBins){Long n=now==null?null:now.best.get(reps),p=before==null?null:before.best.get(reps);b.metric(domain,path+"bestLoadGramsByReps["+reps+"]",n,"grams","ASSISTANCE".equals(description.mode)?"minimum_assistance_at_equal_reps":"maximum_entered_load_at_equal_reps",now==null?0:now.sets);if(selection.compare&&description.comparable&&n!=null&&p!=null){long delta=n-p,improvement="ASSISTANCE".equals(description.mode)?p-n:delta;String compare="exercise[e"+ref+"].reps["+reps+"].";b.comparison(domain,compare+"loadDeltaGrams",delta,"grams","current_minus_previous_same_equipment_reps",Math.min(now.sets,before.sets));b.comparison(domain,compare+"improvementGrams",improvement,"grams","ASSISTANCE".equals(description.mode)?"previous_minus_current_assistance":"current_minus_previous_load",Math.min(now.sets,before.sets));b.comparison(domain,compare+"loadDeltaPercent",p>0?AnalysisHealthSummary.round(100.0*delta/p,1):null,"percent","delta_divided_by_positive_previous_load",Math.min(now.sets,before.sets));b.metric(domain,path+"generalizedChangeEligible",now.sessions.size()>=2&&before.sessions.size()>=2,"boolean","at_least_two_sessions_each_window",Math.min(now.sessions.size(),before.sessions.size()));}if(selection.focused&&now!=null)for(Map.Entry<Integer,Map<Integer,Long>> day:now.daily.entrySet())if(day.getValue().containsKey(reps))b.metric(domain,path+"day["+day.getKey()+"].bestLoadGramsByReps["+reps+"]",day.getValue().get(reps),"grams","same_mode_equipment_and_reps",1);}
        }
        b.metric(domain,"period.missingEquipmentExerciseCount",missingEquipment,"count","selected_machine_or_assistance_without_identity",selection.exercises.size(),"MISSING_EQUIPMENT_ID");if(selection.compare&&current.sessions>=2&&previous.sessions>=2){b.comparison(domain,"savedSessionCountDelta",current.sessions-previous.sessions,"count","current_minus_previous_saved_sessions",Math.min(current.sessions,previous.sessions));b.comparison(domain,"doneWorkSetCountDelta",current.sets-previous.sets,"count","current_minus_previous_done_work_sets",Math.min(current.sessions,previous.sessions));b.comparison(domain,"totalRepsDelta",current.reps-previous.reps,"reps","current_minus_previous_registered_reps",Math.min(current.sessions,previous.sessions));}b.question(domain,"STRENGTH_RECORDED_WORK_CHANGE","STRENGTH_COMPARABILITY_GAPS");if(selection.compare&&!selection.repBins.isEmpty()&&!selection.exercises.isEmpty())b.question(domain,"STRENGTH_COMPARABLE_LOAD_CHANGE");
        // A paired strength value is permitted only for one explicit exercise/repetition context.
        if(selection.exercises.size()==1&&selection.repBins.size()==1){Exercise e=current.exercises.get(selection.exercises.get(0));if(e!=null&&e.comparable)for(Map.Entry<Integer,Map<Integer,Long>> day:e.daily.entrySet()){Long grams=day.getValue().get(selection.repBins.get(0));if(grams!=null)b.daily.get("strength").put(day.getKey(),grams.doubleValue());}}
    }
    private static void best(Map<Integer,Long> map,int reps,long grams,String mode){Long old=map.get(reps);if(old==null||("ASSISTANCE".equals(mode)?grams<old:grams>old))map.put(reps,grams);}
    private AnalysisStrengthSummary(){}
}

